/**
 * @file Board.js
 *
 * @description The `Board` component renders the game board for "Člověče, nezlob se!".
 *              It handles real-time updates, manages player and piece states,
 *              processes tile clicks, and communicates with the server through socket events.
 * 
 * @author Karolína Virágová (xvirag00)
 */

import React, { useState, useMemo, useEffect } from 'react';
import './Board.css';
import { getCoordinatesFromValue } from './coordinates.js';
import Ended from './Ended';

const Board = ({ gameData, setGameData, socket, handleReturnToMainScreen }) => {
  const gridSize = 11; // Size of the game board (11x11 grid)
  const centerIndex = Math.floor(gridSize / 2); // Center index of the board (5 for 11x11)
  const [players, setPlayers] = useState(gameData.players || []);
  const [pieces, setPieces] = useState(gameData.board.pieces || []);
  const [error, setError] = useState(null);
  const [statusMessage, setStatusMessage] = useState("");
  const [diceRoll, setDiceRoll] = useState(null);
  const [gameEnded, setGameEnded] = useState(false);
  const [score, setScore] = useState([]);
  const [houseLength, setHouseLength] = useState(0);

  // Socket event handling
  useEffect(() => {
    if (!socket) return;

    const handleGameUpdates = (data) => {
      const { updatedPiece } = data;
      if (!updatedPiece) {
        console.error('No updatedPiece received from server!');
        return;
      }

      setPieces((prevPieces) => {
        const updatedPieces = [...prevPieces];
        const pieceIndex = updatedPieces.findIndex(piece => piece.id === updatedPiece.id);
        if (pieceIndex === -1) {
          console.error(`Piece with ID ${updatedPiece.id} not found in state!`);
          return prevPieces;
        }
        updatedPieces[pieceIndex] = { ...updatedPieces[pieceIndex], commonPosition: updatedPiece.commonPosition };
        return updatedPieces;
      });

      socket.emit('game:play');
    };

    const handleDiceRoll = (data) => {
      const { playerId, dice, canDeploy } = data;
      const player = players.find(p => p.id === playerId);
      setDiceRoll(dice);
      const playerName = player ? player.name : 'Unknown Player';
      setStatusMessage(`Player ${playerName} rolled a ${dice}.`);

      if (canDeploy) {
        setStatusMessage(`Player ${playerName} can deploy a new piece!`);
        socket.emit('game:deployPiece');
      }
    };

    socket.on('game:updated', handleGameUpdates);
    socket.on('game:diceRolled', handleDiceRoll);

    socket.on('game:started', (gameState) => {
      setGameData(gameState);
      setPlayers(gameState.players || []);
      setPieces(gameState.board.pieces || []);
      socket.emit('game:play');
    });

    socket.on('game:ended', (data) => {
      setGameEnded(true);
      setScore(data.score);
      setHouseLength(data.houseLength);
    });

    return () => {
      socket.off('game:updated', handleGameUpdates);
      socket.off('game:diceRolled', handleDiceRoll);
      socket.off('game:started');
      socket.off('game:ended');
    };
  }, [socket, players]);

  const startNewGame = () => {
    setScore([]);
    setPieces([]);
    setHouseLength(0);
    setGameEnded(false);
    socket.emit('game:start', { fillWithBots: false }, (response) => {
      if (response?.board?.pieces) {
        setPieces(response.board.pieces);
      }
    });
  };

  // Tile color map based on players
  const tileColorMap = useMemo(() => {
    const colorMap = new Map();
    players.forEach((player, index) => {
      const tiles = [
        // Add specific tiles for each player based on the index
        index === 0 ? [[4, 0], [5, 1], [5, 2], [5, 3], [5, 4], [0, 0], [0, 1], [1, 0], [1, 1]] : [],
        index === 1 ? [[0, 6], [1, 5], [2, 5], [3, 5], [4, 5], [0, 9], [0, 10], [1, 9], [1, 10]] : [],
        index === 2 ? [[6, 10], [5, 6], [5, 7], [5, 8], [5, 9], [9, 9], [10, 9], [9, 10], [10, 10]] : [],
        index === 3 ? [[10, 4], [6, 5], [7, 5], [8, 5], [9, 5], [9, 0], [9, 1], [10, 0], [10, 1]] : []
      ].flat();
      tiles.forEach(([row, col]) => colorMap.set(`${row}-${col}`, player.color));
    });
    return colorMap;
  }, [players]);

  const pieceMap = useMemo(() => {
    const map = new Map();
    pieces.forEach(piece => {
      const { row, col } = getCoordinatesFromValue(piece.commonPosition);
      map.set(`${row}-${col}`, piece);
    });
    return map;
  }, [pieces]);

  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) return false;
    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  const getTileColor = (row, col) => isCrossTile(row, col) ? tileColorMap.get(`${row}-${col}`) || 'white' : 'white';

  const renderPiece = (row, col) => {
    const piece = pieceMap.get(`${row}-${col}`);
    return piece ? (
      <div
        className="piece"
        style={{
          backgroundColor: piece.color,
          border: '2px solid black',
          width: '70%',
          height: '70%',
        }}
      />
    ) : null;
  };

  const handleTileClick = (row, col) => {
    const clickedPiece = pieceMap.get(`${row}-${col}`);
    if (clickedPiece) {
      socket.emit('game:movePiece', { commonPosition: clickedPiece.commonPosition }, (data) => {
        setError(data ? "Failed to send position." : null);
        setStatusMessage(data ? "" : "Position sent successfully.");
      });
    } else {
      setError("No piece on this tile to select.");
    }
  };

  return (
    <div className="board-container">
      {gameEnded ? (
        <Ended
          score={score}
          players={players}
          houseLength={houseLength}
          onReturnToApp={handleReturnToMainScreen}
          onNewGame={startNewGame}
        />
      ) : (
        <>
          {statusMessage && <div className="status-message">{statusMessage}</div>}
          {error && <div className="error">{error}</div>}
          <div className="board">
            {Array.from({ length: gridSize }).map((_, row) => (
              <div key={row} className="board-row">
                {Array.from({ length: gridSize }).map((_, col) => (
                  <div
                    key={`${row}-${col}`}
                    className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
                    style={{ backgroundColor: getTileColor(row, col) }}
                    onClick={() => handleTileClick(row, col)}
                  >
                    {renderPiece(row, col)}
                  </div>
                ))}
              </div>
            ))}
          </div>
          {players.map((player, index) => (
            <div key={index} className={`player-name player-${index + 1}`}>
              {player.name}
            </div>
          ))}
        </>
      )}
    </div>
  );
};

export default Board;
